    const shots = [];
    for (let f = 0; f < 120; f++) for (const sub of [0.02, 0.5]) { await go(p, f, sub); shots.push(await shot(p)); }
    const L = await p.evaluate(eval(LUM), shots);
    let maxRel = 0, big = 0, flashTimes = [];
    for (let i = 1; i < L.length; i++) {
      const rel = Math.abs(L[i] - L[i-1]) / Math.max(L[i], L[i-1]);
      maxRel = Math.max(maxRel, rel);
      if (Math.abs(L[i] - L[i-1]) >= 0.1 * Math.max(L[i], L[i-1])) { big++; flashTimes.push((i / 2 / 12).toFixed(2)); }
    }
    console.log(`[4] mean lum range ${Math.min(...L).toFixed(4)}..${Math.max(...L).toFixed(4)}; max step-to-step relative change ${(maxRel * 100).toFixed(1)}%; changes >=10%: ${big} at t=${flashTimes.slice(0, 12).join(',')}`);
    await p.close();
  }

  // 3. render cost (CPU+GPU, synchronised by a 1px readPixels) at several pixel counts
  for (const [w, h, dpr] of [[1280, 800, 1], [1280, 800, 2], [2560, 1440, 2], [390, 844, 3]]) {
    const p = await open(file, w, h, dpr);
    await go(p, 0);
    const ms = await p.evaluate(async () => {
      const gl = __gls[0]; const px = new Uint8Array(4); const t = [];
      for (let f = 1; f <= 24; f++) {
        __vc.set((f + 0.02) * 1000 / 12);
        const a = performance.now === undefined ? 0 : 0;
