  if (u < SNAP) return { g: -0.35 * Math.sin(Math.PI * u / SNAP), v: 99 };
  const v = (u - SNAP) * BEAT;
  const g = ((1 - Math.exp(-v * 12)) + 0.45 * Math.sin(v * 18) * Math.exp(-v * 4.5))
          * (1 - smooth(1.2, (1 - SNAP) * BEAT, v));
  return { g, v };
}
function smooth(a, b, x) { const t = Math.min(Math.max((x - a) / (b - a), 0), 1); return t * t * (3 - 2 * t); }

function step(frame) {
  const tq = frame / FPS, ph = TAU * tq / LOOP;

  const b0 = beat(tq, 0), b1 = beat(tq, BEAT / 2), b2 = beat(tq, BEAT / 4);
  const m0 = { x: 2.4 * Math.cos(ph), z: 2.4 * Math.sin(ph), s: 1.25 * (0.72 + 0.42 * b0.g), r: 0.0, b: b0 };
  const m1 = { x: 1.7 * Math.cos(-2 * ph + 1.3), z: 1.3 * Math.sin(-2 * ph + 1.3), s: 1.0 * (0.72 + 0.42 * b1.g), r: 0.35, b: b1 };
  const auto = { x: 1.3 * Math.sin(3 * ph), z: 1.0 * Math.sin(2 * ph + 0.5), s: 1.1 * (0.72 + 0.42 * b2.g) };

  // pointer magnet: a damped spring (stateful), blended in only while the pointer is in use
  const active = performance.now() - pointer.last < 2500 || pointer.down;
  pm.w += ((active ? 1 : 0) - pm.w) * 0.35;
  if (pm.w < 0.002) pm.w = 0;
  const tx = active ? pointer.x : auto.x, tz = active ? pointer.z : auto.z;
  const ts = pointer.down ? 2.1 : 1.55;
  if (pm.w === 0) { pm.x = auto.x; pm.z = auto.z; pm.vx = pm.vz = 0; pm.s = ts; pm.vs = 0; }
  pm.vx = pm.vx * 0.45 + (tx - pm.x) * 0.5; pm.x += pm.vx;
  pm.vz = pm.vz * 0.45 + (tz - pm.z) * 0.5; pm.z += pm.vz;
  pm.vs = pm.vs * 0.55 + (ts - pm.s) * 0.45; pm.s += pm.vs;
  if (pointer.plucked > 0) { pm.pluckV = 0; pointer.plucked = 0; } else pm.pluckV += 1 / FPS;

  const w = pm.w;
  const m2 = {
    x: auto.x + (pm.x - auto.x) * w, z: auto.z + (pm.z - auto.z) * w,
    s: auto.s + (pm.s - auto.s) * w, r: 0.7,
    b: w > 0.5 && pm.pluckV < 3 ? { v: pm.pluckV } : b2
  };

  [m2, m0, m1].forEach((m, i) => {
    uniforms.uMag.value[i].set(m.x, m.z, m.s, m.r);
    uniforms.uBeat.value[i].set(m.b.v, 0.008, 0, 0);
    const g = markers[i];
    const y = 1.95 - 0.6 * Math.min(m.s, 1.8) / 1.8;
    g.position.set(m.x, y, m.z);
    g.userData.ring.scale.setScalar(0.75 + 0.35 * m.s);
    g.userData.stem.scale.y = y; g.userData.stem.position.y = -y / 2;
  });

  // camera: a slow periodic sway plus a little gate weave, as in a hand-cranked projector
  const weave = reduceMotion ? 0 : 0.03;
  camera.position.set(0.9 * Math.sin(ph) + (hash(frame) - 0.5) * weave,
                      6.4 + 0.3 * Math.cos(2 * ph) + (hash(frame + 31) - 0.5) * weave, 8.4);
  camera.lookAt(0, 0, 0.9);
  uniforms.uCam.value.copy(camera.position);
  uniforms.uFrame.value = frame;

  // Photosensitive safety (WCAG 2.3.1, measured per screen region): luminance steps stay under 0.04 of the
  // 0.1 flash threshold, and snap flashes come at most 0.4 times a second.
  uniforms.uFlick.value = reduceMotion ? 1 : 0.965 + 0.05 * hash(frame + 7);
  const snapFrame = b0.v >= 0 && b0.v < 1 / FPS;
  flash.style.opacity = reduceMotion ? '0' : (snapFrame ? 0.16 : 0).toFixed(3);

  frameEl.textContent = 'frame ' + String(frame + 1).padStart(3, '0') + ' / ' + FRAMES;
}

resize();
const start = performance.now();
function loop(now) {
  const t = ((now - start) / 1000) % LOOP;
  const frame = Math.floor(t * FPS) % FRAMES;
  if (frame !== lastFrame) {
    lastFrame = frame;
    step(frame);
    renderer.render(scene, camera);
  }
  // between images, the drum keeps turning and the shutter dips a little: the zoetrope's own flicker
  drawDrum(t);
  if (!reduceMotion) {
    const fp = (t * FPS) % 1;
    shutter.style.opacity = (0.05 * (1 - smooth(0, 0.3, fp))).toFixed(3);
  }
  requestAnimationFrame(loop);
}

